            d["Compiled game shaders. Games rebuild them, so the first launch after cleaning can stutter for a minute. Close all games first. Tip: cap it in NVIDIA Control Panel > Manage 3D settings > Shader Cache Size."] = "שיידרים מקומפלים של משחקים. המשחקים בונים אותם מחדש, לכן ההפעלה הראשונה אחרי הניקוי עלולה לגמגם דקה. סגרו קודם את כל המשחקים. טיפ: הגבילו בלוח הבקרה של NVIDIA > ניהול הגדרות תלת-ממד > גודל מטמון שיידרים.";
            d["Pieces of videos you streamed. Stremio must be closed; the cleaner offers to close it. Tip: set a limit in Stremio > Settings > Streaming > Caching."] = "חלקים של סרטונים שצפית בהם. Stremio צריך להיות סגור; הניקוי מציע לסגור אותו. טיפ: קבעו מגבלה ב-Stremio > הגדרות > סטרימינג > מטמון.";
            d["Temporary files left by apps and installers. Files still in use are skipped automatically."] = "קבצים זמניים שהשאירו אפליקציות ומתקינים. קבצים בשימוש מדולגים אוטומטית.";
            d["Temporary files left by Windows and installers. Files still in use are skipped."] = "קבצים זמניים שהשאירו Windows ומתקינים. קבצים בשימוש מדולגים.";
            d["Update files that are already installed. Run this when Windows Update is not in the middle of installing. Windows Update is paused for a moment and started again."] = "קובצי עדכון שכבר הותקנו. הריצו כש-Windows Update לא באמצע התקנה. Windows Update נעצר לרגע ומופעל מחדש.";
            d["Update pieces Windows shares with other PCs. Cleared with the official Windows command."] = "חלקי עדכונים ש-Windows משתף עם מחשבים אחרים. מנוקה בפקודה הרשמית של Windows.";
            d["Windows shader cache. Games rebuild it."] = "מטמון השיידרים של Windows. המשחקים בונים אותו מחדש.";
            d["Picture previews in File Explorer. Rebuilt automatically. Files Explorer is using are skipped."] = "תצוגות מקדימות של תמונות בסייר הקבצים. נבנות מחדש אוטומטית. קבצים שהסייר משתמש בהם מדולגים.";
            d["Reports Windows saved after app crashes."] = "דוחות ש-Windows שמר אחרי קריסות אפליקציות.";
            d["Memory snapshots from past crashes. Only useful if you are investigating a crash."] = "תמונות זיכרון מקריסות קודמות. שימושיות רק אם חוקרים קריסה.";
            d["Archived Windows Update logs. The current log is kept."] = "יומנים ישנים של Windows Update. היומן הנוכחי נשמר.";
            d["Microsoft's own tool removes replaced versions of Windows components. Safe, but takes 5-20 minutes. Size is only known after it runs."] = "הכלי של Microsoft מסיר גרסאות שהוחלפו של רכיבי Windows. בטוח, אבל לוקח 5-20 דקות. הגודל ידוע רק אחרי ההרצה.";
            d["Cached web pages and images. Passwords, history and logins are kept. Chrome must be closed; the cleaner offers to close it."] = "דפי אינטרנט ותמונות שמורים. סיסמאות, היסטוריה והתחברויות נשמרים. Chrome צריך להיות סגור; הניקוי מציע לסגור אותו.";
            d["Cached web pages and images. Passwords, history and logins are kept. Edge must be closed; the cleaner offers to close it."] = "דפי אינטרנט ותמונות שמורים. סיסמאות, היסטוריה והתחברויות נשמרים. Edge צריך להיות סגור; הניקוי מציע לסגור אותו.";
            d["Permanently deletes everything in the Recycle Bin. Check it first if unsure."] = "מוחק לצמיתות את כל מה שבסל המיחזור. בדקו אותו קודם אם אתם לא בטוחים.";
            d["Setup files left from a past Windows upgrade. Delete only if no Windows version upgrade is in progress right now. Moved to Undo for 7 days first."] = "קובצי התקנה שנשארו משדרוג Windows קודם. למחוק רק אם אין שדרוג גרסה בתהליך כרגע. עוברים קודם לביטול ל-7 ימים.";
            d["Leftovers from updating the Windows recovery environment. Delete after updates have finished and you have restarted. Moved to Undo for 7 days first."] = "שאריות מעדכון סביבת השחזור של Windows. למחוק אחרי שהעדכונים הסתיימו והמחשב הופעל מחדש. עוברים קודם לביטול ל-7 ימים.";
            d["Update packages Adobe Reader already installed. Reader keeps working; its updater downloads again if it needs to. Moved to Undo for 7 days first."] = "חבילות עדכון ש-Adobe Reader כבר התקין. Reader ממשיך לעבוד; המעדכן שלו מוריד שוב אם צריך. עוברות קודם לביטול ל-7 ימים.";
            d["The old Windows kept after a big upgrade, so you can go back for 10 days. Removing it means you can no longer go back. Windows' own Disk Cleanup removes it (10-30 minutes). Too big for Undo."] = "ה-Windows הקודם שנשמר אחרי שדרוג גדול, כדי שאפשר יהיה לחזור אחורה 10 ימים. הסרה פירושה שכבר לא ניתן לחזור. ניקוי הדיסק של Windows מסיר אותו (10-30 דקות). גדול מדי לביטול.";
            d["Images and code Discord downloaded. Your messages and settings are kept. Discord must be closed."] = "תמונות וקוד ש-Discord הוריד. ההודעות וההגדרות שלך נשמרות. Discord צריך להיות סגור.";
            d["Cached pictures and web files. Your chats are kept online. Teams must be closed."] = "תמונות וקובצי אינטרנט שמורים. הצ'אטים נשמרים ברשת. Teams צריך להיות סגור.";
            d["Songs Spotify cached for streaming. If you downloaded songs for offline listening they may need to download again. Spotify must be closed."] = "שירים ש-Spotify שמר לסטרימינג. אם הורדת שירים להאזנה לא מקוונת ייתכן שיצטרכו לרדת שוב. Spotify צריך להיות סגור.";
            d["Store pages and logs the launcher saved. Your games are not touched. The launcher must be closed."] = "דפי חנות ויומנים שהמשגר שמר. המשחקים לא נוגעים. המשגר צריך להיות סגור.";
            d["Web cache of the EA app. Your games are not touched. The EA app must be closed."] = "מטמון האינטרנט של אפליקציית EA. המשחקים לא נוגעים. אפליקציית EA צריכה להיות סגורה.";
            d["Steam's web cache and game shader caches. Games rebuild shaders (short stutter the first time). Your games are not touched. Steam must be closed."] = "מטמון האינטרנט של Steam ומטמוני שיידרים של משחקים. המשחקים בונים שיידרים מחדש (גמגום קצר בפעם הראשונה). המשחקים לא נוגעים. Steam צריך להיות סגור.";
            d["VS Code's caches and logs. Settings, extensions and open folders are kept. VS Code must be closed."] = "מטמונים ויומנים של VS Code. הגדרות, הרחבות ותיקיות פתוחות נשמרים. VS Code צריך להיות סגור.";
            d["Older copies of extensions that were updated. The newest version of each extension is kept. VS Code must be closed."] = "עותקים ישנים של הרחבות שעודכנו. הגרסה החדשה של כל הרחבה נשמרת. VS Code צריך להיות סגור.";
            d["Older versions the Claude app kept after updating. The newest version is kept; files in use are skipped."] = "גרסאות ישנות שאפליקציית Claude שמרה אחרי עדכון. הגרסה החדשה נשמרת; קבצים בשימוש מדולגים.";
            d["Package download caches. Tools download again when needed (needs internet). Projects are not touched."] = "מטמוני הורדת חבילות. הכלים מורידים שוב כשצריך (נדרש אינטרנט). הפרויקטים לא נוגעים.";
            d["All NuGet packages your .NET projects use. They are downloaded again on the next build (needs internet; slower first build). Close Visual Studio first."] = "כל חבילות NuGet שפרויקטי ה-.NET שלך משתמשים בהן. הן יורדות שוב בבנייה הבאה (נדרש אינטרנט; בנייה ראשונה איטית יותר). סגרו קודם את Visual Studio.";
            d["Photos, videos and files Telegram downloaded while you chatted. Everything stays in Telegram's cloud and downloads again when you open it. Telegram must be closed."] = "תמונות, סרטונים וקבצים ש-Telegram הוריד בזמן הצ'אט. הכול נשאר בענן של Telegram ויורד שוב כשפותחים. Telegram צריך להיות סגור.";
            d["WhatsApp's web cache on this PC. Your chats and media are kept. WhatsApp must be closed."] = "מטמון האינטרנט של WhatsApp במחשב הזה. הצ'אטים והמדיה נשמרים. WhatsApp צריך להיות סגור.";
            d["Zoom's web cache and logs. Recordings and settings are kept. Zoom must be closed."] = "מטמון האינטרנט והיומנים של Zoom. הקלטות והגדרות נשמרות. Zoom צריך להיות סגור.";
            d["Cached web pages and images. History, passwords and logins are kept. The browsers must be closed."] = "דפי אינטרנט ותמונות שמורים. היסטוריה, סיסמאות והתחברויות נשמרים. הדפדפנים צריכים להיות סגורים.";
            d["Stopped containers, unused networks, dangling images and build cache, removed with Docker's own prune command. Running containers and images in use are kept. Docker Desktop must be running."] = "קונטיינרים עצורים, רשתות לא בשימוש, אימג'ים יתומים ומטמון בנייה, מוסרים בפקודת prune של Docker. קונטיינרים רצים ואימג'ים בשימוש נשמרים. Docker Desktop צריך לרוץ.";
            d["Driver and app installers the NVIDIA app downloaded for updates. Moved to Undo for 7 days first. The NVIDIA app downloads again if it needs them."] = "מתקיני דרייברים ואפליקציות שאפליקציית NVIDIA הורידה לעדכונים. עוברים קודם לביטול ל-7 ימים. אפליקציית NVIDIA תוריד שוב אם תצטרך.";
            d["Sites you visited, the address-bar suggestions and the most-visited tiles. Passwords, bookmarks and saved logins are not touched. Close the browser first."] = "אתרים שביקרת בהם, הצעות שורת הכתובת והאריחים של האתרים הנפוצים. סיסמאות, סימניות והתחברויות שמורות לא נוגעים. סגרו קודם את הדפדפן.";
            d["Remove trackers and site data. You will be signed out of websites. Close the browser first."] = "מסיר עוקבים ונתוני אתרים. תצטרכו להתחבר מחדש לאתרים. סגרו קודם את הדפדפן.";
            d["Remove trackers and site data. You will be signed out of websites. Your Firefox history and bookmarks are not touched."] = "מסיר עוקבים ונתוני אתרים. תצטרכו להתחבר מחדש לאתרים. ההיסטוריה והסימניות של Firefox לא נוגעים.";
            d["The lists of files you opened lately (Explorer Quick access, taskbar right-click lists). Also clears items you pinned in those lists. The files themselves are not touched."] = "רשימות הקבצים שפתחת לאחרונה (גישה מהירה בסייר, רשימות בלחיצה ימנית בשורת המשימות). מנקה גם פריטים שהוצמדו לרשימות האלה. הקבצים עצמם לא נוגעים.";
            d["What you typed in Win+R and Explorer's address and search bars, and the recent folders in Open/Save windows."] = "מה שהוקלד ב-Win+R ובשורות הכתובת והחיפוש של הסייר, והתיקיות האחרונות בחלונות פתיחה/שמירה.";
            d["Empties what you last copied (a password or a message you copied stays there until you copy something else)."] = "מרוקן את מה שהעתקת לאחרונה (סיסמה או הודעה שהועתקה נשארת שם עד שמעתיקים משהו אחר).";
            d["The list of websites this PC looked up recently. Windows fills it again as you browse."] = "רשימת האתרים שהמחשב חיפש לאחרונה. Windows ממלא אותה שוב תוך כדי גלישה.";
            d["Windows system files"] = "קובצי מערכת של Windows";
            d["Never delete."] = "לעולם לא למחוק.";
            d["Installed programs"] = "תוכנות מותקנות";
            d["Installed programs (32-bit)"] = "תוכנות מותקנות (32 סיביות)";
            d["Never delete by hand. Uninstall apps you don't use in the Apps tab."] = "לא למחוק ידנית. הסירו אפליקציות שלא בשימוש בלשונית אפליקציות.";
            d["Shared app data"] = "נתוני אפליקציות משותפים";
            d["Never delete by hand. Shrinks when apps are uninstalled."] = "לא למחוק ידנית. קטן כשמסירים אפליקציות.";
            d["Installer cache"] = "מטמון המתקין";
            d["Never delete. Breaks repair and uninstall of apps."] = "לעולם לא למחוק. שובר תיקון והסרה של אפליקציות.";
            d["Page file"] = "קובץ ההחלפה";
            d["Managed by Windows. Leave it."] = "מנוהל על ידי Windows. להשאיר.";
            d["Previous Windows (Windows.old)"] = "Windows הקודם (Windows.old)";
            d["Remove with Elixar: Cleaner > Previous Windows installation."] = "להסיר עם Elixar: ניקוי > התקנת Windows הקודמת.";
            d["Upgrade leftovers ($WINDOWS.~BT)"] = "שאריות שדרוג ($WINDOWS.~BT)";
            d["Remove with Elixar together with Windows.old (Cleaner)."] = "להסיר עם Elixar יחד עם Windows.old (ניקוי).";
            d["Upgrade media ($GetCurrent)"] = "קובצי שדרוג ($GetCurrent)";
            d["Delete with Elixar if no Windows upgrade is in progress."] = "למחוק עם Elixar אם אין שדרוג Windows בתהליך.";
            d["Delete with Elixar after updates finish and you restart."] = "למחוק עם Elixar אחרי שהעדכונים הסתיימו והמחשב הופעל מחדש.";
            d["Adobe Reader update cache"] = "מטמון העדכונים של Adobe Reader";
            d["Delete old update packages with Elixar."] = "למחוק חבילות עדכון ישנות עם Elixar.";
            d["Component store (WinSxS)"] = "מאגר הרכיבים (WinSxS)";
            d["Clean only with DISM (option in Elixar). Size is overstated because of hard links."] = "לנקות רק עם DISM (אפשרות ב-Elixar). הגודל מוגזם בגלל קישורים קשיחים.";
            d["Shrink or turn off with Elixar: Tools > System space > Hibernation file."] = "להקטין או לכבות עם Elixar: כלים > שטח מערכת > קובץ שינה.";
            d["Windows logs"] = "יומני Windows";
            d["Old servicing logs can be cleared with Elixar."] = "אפשר לנקות יומני שירות ישנים עם Elixar.";
            d["Downloads folder"] = "תיקיית ההורדות";
            d["Sort by size, delete old installers and archives."] = "מיינו לפי גודל, מחקו מתקינים וארכיונים ישנים.";
            d["Empty it once you are sure nothing in it is needed."] = "רוקנו כשבטוח ששום דבר בו לא נחוץ.";
            d["Videos folder"] = "תיקיית הסרטונים";
            d["Move large videos to an external drive or cloud."] = "העבירו סרטונים גדולים לכונן חיצוני או לענן.";
            d["Desktop"] = "שולחן העבודה";
            d["Review large files you no longer need."] = "בדקו קבצים גדולים שכבר לא צריך.";
            d["Clear with Elixar (close games first)."] = "לנקות עם Elixar (סגרו קודם משחקים).";
            d["Clear with Elixar or set a limit in Stremio settings."] = "לנקות עם Elixar או לקבוע מגבלה בהגדרות Stremio.";
            d["Safe to clear. Files in use are skipped automatically."] = "בטוח לניקוי. קבצים בשימוש מדולגים אוטומטית.";
            d["Safe to clear."] = "בטוח לניקוי.";
            d["Safe after updates finished installing."] = "בטוח אחרי שהעדכונים סיימו להתקין.";
            d["Crash dumps (small)"] = "קובצי קריסה (קטנים)";
            d["Safe unless you are investigating a crash."] = "בטוח אלא אם חוקרים קריסה.";
            d["Crash dump (full)"] = "קובץ קריסה (מלא)";
            d["Rebuilt automatically."] = "נבנה מחדש אוטומטית.";
            d["Games rebuild it."] = "המשחקים בונים אותו מחדש.";
            d["Clear with Elixar (Chrome closed)."] = "לנקות עם Elixar (Chrome סגור).";
            d["Clear with Elixar (Edge closed)."] = "לנקות עם Elixar (Edge סגור).";
            d["Disk health"] = "בריאות הכוננים";
            d["Back up files..."] = "גיבוי קבצים...";
            d["Windows' Disks & volumes"] = "דיסקים ואמצעי אחסון של Windows";
            d["Reads the health, wear and error counters your drives keep about themselves (the same data Windows uses), so you hear about a failing drive before you lose files. Elixar only reads: nothing is written to the drives, nothing is downloaded and nothing is sent anywhere."] = "קורא את נתוני הבריאות, השחיקה והשגיאות שהכוננים שומרים על עצמם (אותם נתונים ש-Windows משתמש בהם), כדי שתדעו על כונן שעומד להיכשל לפני שקבצים הולכים לאיבוד. Elixar רק קורא: שום דבר לא נכתב לכוננים, שום דבר לא מורד ושום דבר לא נשלח לשום מקום.";
            d["Drive"] = "כונן";
            d["Health"] = "מצב";
            d["Life left"] = "חיים שנותרו";
            d["Temperature"] = "טמפרטורה";
            d["Errors"] = "שגיאות";
            d["Powered on"] = "זמן פעולה";
            d["Reading your drives (a few seconds)..."] = "קורא את הכוננים (כמה שניות)...";
            d["May fail soon"] = "עלול להיכשל בקרוב";
            d["Needs attention"] = "דורש תשומת לב";
            d["Healthy"] = "תקין";
            d["Unknown"] = "לא ידוע";
            d["NVMe SSD"] = "SSD מסוג NVMe";
            d["SATA SSD"] = "SSD מסוג SATA";
            d["SATA hard disk"] = "דיסק קשיח SATA";
            d["hard disk"] = "דיסק קשיח";
            d["USB drive"] = "כונן USB";
            d["USB SSD"] = "SSD בחיבור USB";
            d["USB hard disk"] = "דיסק קשיח בחיבור USB";
            d["drive"] = "כונן";
            d["virtual drive"] = "כונן וירטואלי";
            d["SAS hard disk"] = "דיסק קשיח SAS";
            d["RAID drive"] = "כונן RAID";
            d["Why:"] = "למה:";
            d["What to do:"] = "מה לעשות:";
            d["Windows says:"] = "Windows מדווח:";
            d["S.M.A.R.T. failure warning:"] = "אזהרת כשל S.M.A.R.T.:";
            d["yes"] = "כן";
            d["no"] = "לא";
            d["Highest temperature recorded:"] = "הטמפרטורה הגבוהה ביותר שנרשמה:";
            d["none"] = "אין";
            d["Disk health: back up now!"] = "בריאות הכוננים: לגבות עכשיו!";
            d["Disk health: check"] = "בריאות הכוננים: לבדוק";
            d["Windows reports this drive as unhealthy."] = "Windows מדווח שהכונן הזה לא תקין.";
            d["The drive's own self-check (S.M.A.R.T.) predicts it will fail soon."] = "הבדיקה העצמית של הכונן (S.M.A.R.T.) צופה שהוא ייכשל בקרוב.";
            d["It has used up all of its rated write life (100%)."] = "הכונן ניצל את כל חיי הכתיבה המדורגים שלו (100%).";
            d["Windows reports a warning for this drive."] = "Windows מדווח על אזהרה לכונן הזה.";
            d["Back up now. Copy your important files to another drive or to the cloud today, then plan to replace this drive. Until it is backed up, avoid moving large amounts of data on it."] = "לגבות עכשיו. העתיקו היום את הקבצים החשובים לכונן אחר או לענן, ואז תכננו להחליף את הכונן. עד שהוא מגובה, הימנעו מהעברת כמויות גדולות של נתונים עליו.";
            d["Let the PC cool down: make sure its air vents are free and nothing heavy is running. Check again later."] = "תנו למחשב להתקרר: ודאו שפתחי האוורור פנויים ושלא רץ משהו כבד. בדקו שוב מאוחר יותר.";
            d["Keep a recent backup of anything important and check again in a few days. Replace the drive if the problem grows."] = "שמרו גיבוי עדכני של כל דבר חשוב ובדקו שוב בעוד כמה ימים. החליפו את הכונן אם הבעיה גדלה.";
            d["Nothing to do."] = "אין מה לעשות.";
            d["Windows did not share enough about this drive to judge it."] = "Windows לא סיפק מספיק מידע על הכונן הזה כדי לשפוט את מצבו.";
            d["Wear, temperature and error counts need administrator rights: open Elixar as administrator to see them."] = "שחיקה, טמפרטורה ומספר שגיאות דורשים הרשאות מנהל: פתחו את Elixar כמנהל כדי לראות אותם.";
            d["Windows can't read wear or temperature through this USB connection; that is normal for many USB drives."] = "Windows לא יכול לקרוא שחיקה או טמפרטורה דרך חיבור ה-USB הזה; זה רגיל בהרבה כונני USB.";
            d["This drive doesn't share its wear and temperature with Windows."] = "הכונן הזה לא משתף את נתוני השחיקה והטמפרטורה שלו עם Windows.";
            d["Windows did not report any drives."] = "Windows לא דיווח על אף כונן.";
            d["Your drive looks healthy."] = "הכונן שלכם נראה תקין.";
            d["No problems found, but Windows did not share enough about every drive."] = "לא נמצאו בעיות, אבל Windows לא סיפק מספיק מידע על כל הכוננים.";
            d["Disk health needs Windows."] = "בריאות הכוננים דורשת Windows.";
            d["Windows did not answer in time. Try again in a moment."] = "Windows לא ענה בזמן. נסו שוב בעוד רגע.";
            d["Apply and restart Elixar"] = "החלה והפעלה מחדש של Elixar";
            d["Choose the language and how Elixar looks. To apply a change, Elixar restarts for a moment; nothing else changes."] = "בחרו את השפה ואת המראה של Elixar. כדי להחיל שינוי, Elixar מופעל מחדש לרגע; שום דבר אחר לא משתנה.";
            d["Wait until Elixar finishes, then apply the change."] = "המתינו ש-Elixar יסיים, ואז החילו את השינוי.";
            d["Installing adds Elixar to the Start menu and to Windows' installed apps list (with Uninstall), in a folder only administrators can change. Start Elixar from the Start menu afterwards: Windows no longer shows its blue \"Windows protected your PC\" box for it."] = "ההתקנה מוסיפה את Elixar לתפריט התחל ולרשימת האפליקציות המותקנות של Windows (עם הסרה), בתיקייה שרק מנהלים יכולים לשנות. אחר כך הפעילו את Elixar מתפריט התחל: Windows כבר לא יציג עבורו את החלון הכחול \"Windows protected your PC\".";
            d["Email reports"] = "דוחות במייל";
            d["Sign in with Google"] = "התחברות עם Google";
            d["Set up Google sign-in (one time)..."] = "הגדרת התחברות עם Google (פעם אחת)...";
            d["Send a test email"] = "שליחת מייל בדיקה";
            d["Sign out"] = "התנתקות";
            d["Sign in again"] = "התחברות מחדש";
            d["Cancel sign-in"] = "ביטול ההתחברות";
            d["Save email settings"] = "שמירת הגדרות המייל";
            d["Weekly auto-clean report: what was cleaned, how much it freed, and what is left for you to decide"] = "דוח הניקוי השבועי: מה נוקה, כמה התפנה, ומה נשאר להחלטתך";
            d["Alerts: C: almost full (your limit in Automation, or 15%), or a drive that may fail"] = "התראות: C: כמעט מלא (הגבול שלך באוטומציה, או 15%), או כונן שעלול להיכשל";
            d["Weekly summary every"] = "סיכום שבועי בכל";
            d["(alerts are checked daily at this time too)"] = "(גם ההתראות נבדקות בשעה זו מדי יום)";
            d["Elixar can only send email, never read your inbox. Emails go from your Gmail to you only, list categories and sizes (never your file names), and never contain a link: to delete anything, open Elixar. Your Google sign-in is encrypted on this PC in a folder only administrators can open."] = "Elixar יכול רק לשלוח מיילים, אף פעם לא לקרוא את תיבת הדואר. המיילים נשלחים מה-Gmail שלך אליך בלבד, מציגים קטגוריות וגדלים (אף פעם לא שמות קבצים), ואף פעם לא מכילים קישור: כדי למחוק משהו, פתחו את Elixar. ההתחברות ל-Google מוצפנת במחשב הזה בתיקייה שרק מנהלים יכולים לפתוח.";
            d["Not signed in."] = "לא מחובר.";
            d["Not signed in. Set up Google sign-in once, then sign in."] = "לא מחובר. הגדירו פעם אחת התחברות עם Google, ואז התחברו.";
            d["Waiting for you to sign in to Google in your browser..."] = "ממתין להתחברות ל-Google בדפדפן...";
            d["Finishing sign-in..."] = "מסיים את ההתחברות...";
            d["Sending a test email..."] = "שולח מייל בדיקה...";
            d["Email settings saved."] = "הגדרות המייל נשמרו.";
            d["Sign out of Google? Elixar stops sending emails and Google cancels its permission."] = "להתנתק מ-Google? Elixar יפסיק לשלוח מיילים ו-Google יבטל את ההרשאה.";
            d["Set up Google sign-in"] = "הגדרת התחברות עם Google";
            d["Set up Google sign-in (one time, about 10 minutes)"] = "הגדרת התחברות עם Google (פעם אחת, כ-10 דקות)";
            d["Elixar has no server of its own, so Google needs to know \"Elixar on your PC\" as your own small app. You do this once, in your Google account:"] = "ל-Elixar אין שרת משלו, ולכן Google צריך להכיר את \"Elixar במחשב שלך\" כאפליקציה קטנה משלך. עושים זאת פעם אחת, בחשבון Google שלך:";
            d["1. Open console.cloud.google.com and sign in. Create a project named Elixar."] = "1. פתחו את console.cloud.google.com והתחברו. צרו פרויקט בשם Elixar.";
            d["2. APIs & Services > Library: find \"Gmail API\" and click Enable."] = "2. APIs & Services > Library: חפשו \"Gmail API\" ולחצו Enable.";
            d["3. Google Auth Platform > Get started: app name Elixar, your email, Audience: External."] = "3. Google Auth Platform > Get started: שם האפליקציה Elixar, המייל שלך, Audience: External.";
            d["4. Data access > Add or remove scopes: tick \".../auth/gmail.send\" (send email on your behalf). Nothing else."] = "4. Data access > Add or remove scopes: סמנו \".../auth/gmail.send\" (שליחת מייל בשמך). שום דבר אחר.";
            d["5. Audience > Publish app (In production). Otherwise Google signs Elixar out every 7 days."] = "5. Audience > Publish app (In production). אחרת Google ינתק את Elixar כל 7 ימים.";
            d["6. Clients > Create client > Application type: Desktop app > Create > Download JSON."] = "6. Clients > Create client > Application type: Desktop app > Create > Download JSON.";
            d["7. Click the button below and choose that file."] = "7. לחצו על הכפתור למטה ובחרו את הקובץ הזה.";
            d["When you sign in, Google shows \"Google hasn't verified this app\" because the app is yours and private. Click Advanced > Go to Elixar. Then allow only \"Send email on your behalf\". Elixar can't read your mail."] = "בהתחברות, Google יציג \"Google hasn't verified this app\" כי האפליקציה שלך ופרטית. לחצו Advanced > Go to Elixar. ואז אשרו רק \"Send email on your behalf\". Elixar לא יכול לקרוא את המיילים שלך.";
            d["A Google client is already set up. You can replace it."] = "כבר הוגדר חיבור ל-Google. אפשר להחליף אותו.";
            d["No Google client set up yet."] = "עדיין לא הוגדר חיבור ל-Google.";
            d["Open Google Cloud console"] = "פתיחת Google Cloud console";
            d["Choose the downloaded file..."] = "בחירת הקובץ שהורד...";
            d["Choose the file you downloaded from Google"] = "בחרו את הקובץ שהורדתם מ-Google";
            d["Done. Close this window and click \"Sign in with Google\"."] = "מוכן. סגרו את החלון ולחצו \"התחברות עם Google\".";
            d["No email sent yet."] = "עדיין לא נשלח מייל.";
            // texts with numbers in them
            Pat(@"Clean (\d+) \((.+)\)", m => "ניקוי " + m.Groups[1].Value + " (" + m.Groups[2].Value + ")");
            Pat(@"Remove (\d+) \((.+)\)\.\.\.", m => "הסרה של " + m.Groups[1].Value + " (" + m.Groups[2].Value + ")...");
            Pat(@"Move (\d+) \((.+)\) to PC", m => "העברת " + m.Groups[1].Value + " (" + m.Groups[2].Value + ") למחשב");
            Pat(@"Copy (\d+) \((.+)\) to PC", m => "העתקת " + m.Groups[1].Value + " (" + m.Groups[2].Value + ") למחשב");
            Pat(@"Made by Elisar   ·   Elixar v(.+)   ·   ", m => "נוצר על ידי Elisar   ·   Elixar v" + m.Groups[1].Value + "   ·   ");
            Pat(@"All (\d+) drives look healthy\.", m => "כל " + m.Groups[1].Value + " הכוננים נראים תקינים.");
            Pat(@"(.+) may fail soon: back up your files now\.", m => m.Groups[1].Value + " עלול להיכשל בקרוב: גבו את הקבצים עכשיו.");
            Pat(@"(.+) needs attention\.( So do (\d+) more\.)?", m => m.Groups[1].Value + " דורש תשומת לב." + (m.Groups[2].Success ? " וגם עוד " + m.Groups[3].Value + "." : ""));
            Pat(@"Only (\d+)% of its rated write life is left\.", m => "נותרו רק " + m.Groups[1].Value + "% מחיי הכתיבה המדורגים שלו.");
            Pat(@"(\d+)% of its rated write life is left\.", m => "נותרו " + m.Groups[1].Value + "% מחיי הכתיבה המדורגים שלו.");
            Pat(@"(\d+) read or write errors could not be fixed by the drive\.", m => m.Groups[1].Value + " שגיאות קריאה או כתיבה שהכונן לא הצליח לתקן.");
            Pat(@"It is running hot: (\d+) °C \((\d+) °C or more is too warm for this kind of drive\)\.", m => "הכונן חם מדי: " + m.Groups[1].Value + " °C (" + m.Groups[2].Value + " °C ומעלה חם מדי לסוג כונן כזה).");
            Pat(@"The drive fixed (\d+) read or write errors by itself\. A few are normal; check again if the number keeps growing\.", m => "הכונן תיקן בעצמו " + m.Groups[1].Value + " שגיאות קריאה או כתיבה. מעט זה רגיל; בדקו שוב אם המספר ממשיך לגדול.");
            Pat(@"It has reached (\d+) °C at some point\. Make sure the PC's air vents are free\.", m => "בשלב כלשהו הוא הגיע ל-" + m.Groups[1].Value + " °C. ודאו שפתחי האוורור של המחשב פנויים.");
            Pat(@"Windows marks this drive: (.+)\.", m => "Windows מסמן את הכונן: " + m.Groups[1].Value + ".");
            Pat(@"(\d+) not fixed", m => m.Groups[1].Value + " לא תוקנו");
            Pat(@"(\d+) fixed by the drive", m => m.Groups[1].Value + " תוקנו על ידי הכונן");
            Pat(@"(\d+) hours", m => m.Groups[1].Value + " שעות");
            Pat(@"(\d+) days", m => m.Groups[1].Value + " ימים");
            Pat(@"([\d.]+) years", m => m.Groups[1].Value + " שנים");
            Pat(@"Signed in as (.+) \(Google\)\. Emails go to this address\.", m => "מחובר בתור " + m.Groups[1].Value + " (Google). המיילים נשלחים לכתובת הזו.");
            Pat(@"Signed in\. A test email was sent to (.+)\.", m => "מחובר. נשלח מייל בדיקה אל " + m.Groups[1].Value + ".");
            Pat(@"Test email sent to (.+)\.", m => "מייל בדיקה נשלח אל " + m.Groups[1].Value + ".");
            Pat(@"Last email: (.+) - (.+) ✓", m => "המייל האחרון: " + m.Groups[1].Value + " - " + T(m.Groups[2].Value) + " ✓");
            Pat(@"The last email didn't go out \((.+)\): (.+)", m => "המייל האחרון לא נשלח (" + m.Groups[1].Value + "): " + T(m.Groups[2].Value));
            Pat(@"Google signed Elixar out on (.+)\. Emails have stopped: click ""Sign in again""\.", m => "Google ניתק את Elixar ב-" + m.Groups[1].Value + ". המיילים הפסיקו: לחצו \"התחברות מחדש\".");
            return d;
        }
    }
}
